function xp_demo_refresh():string{global $pdo;$main=$pdo;$demo=xp_demo_connection();$expected=json_decode(xp_setting('demo_tables','[]'),true);$tables=$demo->query('SELECT table_name FROM information_schema.tables WHERE table_schema=DATABASE() ORDER BY table_name')->fetchAll(PDO::FETCH_COLUMN);sort($tables);if(!$expected||$tables!==$expected)throw new RuntimeException('Demo schema differs from the provisioned sandbox. Refresh refused; review it with the platform team.');foreach($tables as $table)if(!preg_match('/^[A-Za-z0-9_]+$/D',$table))throw new RuntimeException('Unsafe demo table name.');$owner=xp_setting('demo_owner');$lock='schoolos-demo-'.substr(hash('sha256',v23secret('xp_demo_name')),0,32);if(!(int)$demo->query('SELECT GET_LOCK('.$demo->quote($lock).',1)')->fetchColumn())throw new RuntimeException('Another demo refresh is running.');q("INSERT INTO xp_config VALUES('demo_refreshing','1') ON DUPLICATE KEY UPDATE value='1'");try{$pdo=$demo;$demo->exec('SET FOREIGN_KEY_CHECKS=0');foreach($tables as $table)$demo->exec('DROP TABLE `'.$table.'`');$demo->exec('SET FOREIGN_KEY_CHECKS=1');xp_demo_seed($owner);return 'The isolated fictional demo was refreshed. Live schools and private configuration were not copied or changed.';}finally{$pdo=$main;$demo->query('SELECT RELEASE_LOCK('.$demo->quote($lock).')');q("UPDATE xp_config SET value='0' WHERE name='demo_refreshing'");}}
